/**
 * Sales-training decks: branching sales scenarios in the study-deck v3 JSON shape.
 *
 * Read-only data. A deck is a list of numbered slides; branching lives in each slide's own `interaction`
 * (a `decision` whose answers open slides, an `outcome` whose buttons open slides) and in `next`.
 * Nothing here stores anything: the JSON is generated by docs/sales-training/generator in hp_erp and
 * is served from /sales-training/<key>/deck.json.
 */

/** There is one course, "G2G Sales Training" for now (more products can be added to the same deck). */
export type SalesProductKey = 'sales'

export const SALES_PRODUCTS: ReadonlyArray<{ key: SalesProductKey; name: string; tagline: string; accent: string }> = [
  { key: 'sales', name: 'G2G Sales Training', tagline: 'Every G2G module, what each role does in it, and a branching sales scenario.', accent: '#0E9F8E' },
]

export interface DecisionOption { id: string; text: string; goto: number }
export interface DecisionInteraction { kind: 'decision'; kicker: string; question: string; options: DecisionOption[] }
export interface OutcomeAction { label: string; goto: number; primary?: boolean }
export interface OutcomeInteraction {
  kind: 'outcome'
  tone: 'sound' | 'caution'
  choice: { id: string; text: string }
  what: string
  why: string
  actions: OutcomeAction[]
}
export type SalesInteraction = DecisionInteraction | OutcomeInteraction

export interface SalesImage { url: string; alt: string; tag?: string; credit?: string }

export interface SalesSlide {
  n: number
  section: string | null
  slide_type: string
  title: string
  content: { body: string; bullets: string[]; key_idea?: string | null }
  interaction: SalesInteraction | null
  /** Where Continue goes; the default is the next slide and -1 means the learner must choose. */
  next?: number
  /** Buttons that open other slides (the module hub and the role views). Each target must exist. */
  links?: Array<{ label: string; goto?: number; href?: string; primary?: boolean; group?: string }>
  /** The product's colour for this slide (each product block has its own). */
  accent?: string
  /** Which top-navigation section this slide belongs to (highlighted in the bar). */
  group?: string
  /** Cover slides: the name and tagline to show (the deck's own cover and each product's cover). */
  product?: { name: string; tagline: string }
  image: SalesImage | null
}

export interface SalesDeck {
  version: number
  title: string
  accent: string
  product: { key: SalesProductKey; name: string; tagline: string }
  slide_count: number
  /** Persistent top navigation: each button opens a slide. */
  nav?: Array<{ label: string; goto: number }>
  teaching_strategy: string | null
  slides: SalesSlide[]
}

export class SalesDeckError extends Error {}

/** Every slide a choice, a button or `next` names must exist. Returns a sentence for the author, or null. */
export function branchProblem(slides: ReadonlyArray<Pick<SalesSlide, 'n' | 'interaction' | 'next' | 'links'>>): string | null {
  const have = new Set(slides.map((s) => s.n))
  for (const s of slides) {
    if (s.next !== undefined && s.next !== -1 && !have.has(s.next)) return `Slide ${s.n} continues to slide ${s.next}, which does not exist`
    const i = s.interaction
    for (const l of s.links ?? []) if (l.goto !== undefined && !have.has(l.goto)) return `Slide ${s.n}'s "${l.label}" opens slide ${l.goto}, which does not exist`
    if (i?.kind === 'decision') for (const o of i.options) if (!have.has(o.goto)) return `Slide ${s.n}'s answer ${o.id} opens slide ${o.goto}, which does not exist`
    if (i?.kind === 'outcome') for (const a of i.actions) if (!have.has(a.goto)) return `Slide ${s.n}'s "${a.label}" opens slide ${a.goto}, which does not exist`
  }
  return null
}

/** Validates a loaded deck. Throws SalesDeckError with a message a person can act on. */
export function parseSalesDeck(raw: unknown): SalesDeck {
  const deck = raw as Partial<SalesDeck> | null
  if (!deck || typeof deck !== 'object') throw new SalesDeckError('The sales-training deck is empty.')
  if (deck.version !== 3) throw new SalesDeckError(`This deck is version ${String(deck.version)}; the player reads version 3.`)
  if (!Array.isArray(deck.slides) || deck.slides.length === 0) throw new SalesDeckError('The deck has no slides.')
  deck.slides.forEach((s, index) => {
    if (typeof s.n !== 'number' || typeof s.title !== 'string' || !s.content) throw new SalesDeckError(`Slide ${index + 1} is malformed.`)
    s.interaction ??= null
    s.content.bullets ??= []
    const i = s.interaction
    if (i?.kind === 'decision' && (!i.question || !Array.isArray(i.options) || i.options.length < 2)) throw new SalesDeckError(`Slide ${s.n} is a decision with fewer than two answers.`)
    if (i?.kind === 'outcome' && (!i.what || !Array.isArray(i.actions) || i.actions.length === 0)) throw new SalesDeckError(`Slide ${s.n} is an outcome with no way on.`)
  })
  for (const b of deck.nav ?? []) if (!deck.slides.some((s) => s.n === b.goto)) throw new SalesDeckError('The navigation button "' + b.label + '" opens slide ' + b.goto + ', which does not exist.')
  const stranded = branchProblem(deck.slides)
  if (stranded) throw new SalesDeckError(`${stranded}.`)
  return deck as SalesDeck
}

/** Where Continue goes from a slide, or null when the learner has to choose. */
export function continueTarget(deck: SalesDeck, slide: SalesSlide): number | null {
  if (slide.next === -1) return null
  const to = slide.next ?? slide.n + 1
  return deck.slides.some((s) => s.n === to) ? to : null
}

/**
 * Which sales-training product a lesson link points at, or null. A lesson's link may be a path or a full address on any host
 * (the host differs between development and production), so only the path is read: .../sales-training/<sc|g2g|eb>[/...].
 */
export function salesTrainingKeyOf(src: string | null | undefined): SalesProductKey | null {
  if (!src) return null
  const path = src.split(/[?#]/)[0]
  // The earlier per-product addresses (sc, g2g, eb) open the same single course.
  return /\/sales-training\/(sales|sc|g2g|eb)(?:\/|$)/.test(path) ? 'sales' : null
}
